import 'package:flutter/material.dart';import '../services/moment_service.dart';import '../widgets/moment_card.dart';
class FavoritesScreen extends StatelessWidget{final MomentService service;const FavoritesScreen({super.key,required this.service});@override Widget build(BuildContext context)=>AnimatedBuilder(animation:service,builder:(_,__){final list=service.favorites;if(list.isEmpty)return const Center(child:Text('Favorite moments will glow here.',style:TextStyle(color:Color(0xFF77736F),fontWeight:FontWeight.w700)));return ListView.separated(padding:const EdgeInsets.fromLTRB(18,18,18,120),itemCount:list.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i){final m=list[i];return MomentCard(moment:m,onFavorite:()=>service.toggleFavorite(m.id),onSave:()=>service.toggleSaved(m.id),onDelete:()=>service.delete(m.id));});});}
